// Auto-generated by r2factor. Manual edits will be overwritten on next split.

use super::misc::read_riff_info_tags;
use super::types::TrackMetadata;
use std::path::Path;

pub(super) fn apply_riff_info_metadata(path: &Path, metadata: &mut TrackMetadata) {
    match read_riff_info_tags(path) {
        Ok(tags) => {
            for (key, value) in tags {
                match key.as_str() {
                    "INAM" | "TITL" => {
                        metadata.title.get_or_insert(value);
                    }
                    "IART" => {
                        metadata.artist.get_or_insert(value);
                    }
                    "IPRD" | "IALB" => {
                        metadata.album.get_or_insert(value);
                    }
                    "ITRK" | "TRCK" => {
                        if metadata.track_number.is_none()
                            && let Some(track_number) = parse_slash_prefixed_u32(&value)
                        {
                            metadata.track_number = Some(track_number);
                        }
                    }
                    "ICRD" | "YEAR" | "DATE" => {
                        if metadata.year.is_none()
                            && let Some(year) = parse_year(&value)
                        {
                            metadata.year = Some(year);
                        }
                    }
                    "IGNR" => {
                        metadata.genre.get_or_insert(value);
                    }
                    _ => {}
                }
            }
        }
        Err(err) => {
            log::debug!(
                "Failed to read RIFF INFO metadata from {}: {}",
                path.display(),
                err
            );
        }
    }
}

pub(super) fn parse_slash_prefixed_u32(value: &str) -> Option<u32> {
    value.split('/').next()?.trim().parse().ok()
}

pub(super) fn parse_year(value: &str) -> Option<u32> {
    value
        .split(['-', '/', ' '])
        .next()
        .and_then(|year| year.trim().parse().ok())
}
